{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "label_pos",
  "per_column": [
    {
      "name": "staff_attitude",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Describes a specific service dimension (staff behavior) extracted from review content. It is an external signal that plausibly correlates with satisfaction without being a restatement of the label; rude/hostile vs friendly categories carry genuine predictive signal."
    },
    {
      "name": "complaint_intensity",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Complaint intensity is essentially a graded measure of dissatisfaction itself, which is nearly synonymous with the (negative) satisfaction label. It restates the outcome on an ordinal scale rather than serving as an independent predictor, so it leaks the focus."
    },
    {
      "name": "unresolved_complaint",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether a complaint was left unresolved is a concrete, content-derived circumstance distinct from the overall polarity label. While correlated, it captures a specific mechanism (resolution failure) that plausibly predicts satisfaction without being a direct restatement of it."
    },
    {
      "name": "revisit_intent",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Stated intent to return/not return is effectively a proxy expression of overall satisfaction (will_not_return ≈ dissatisfied). It is a near-restatement of the focus rather than an independent predictor, and behaves as leakage."
    }
  ],
  "n_predictors": 2,
  "predictive_utility": 0.4,
  "rationale": "Two of four columns (staff_attitude, unresolved_complaint) are legitimate content-derived predictors that isolate specific service dimensions carrying signal about satisfaction. The other two (complaint_intensity, revisit_intent) are near-restatements/proxies of overall satisfaction and constitute leakage. As a set they offer moderate genuine predictive leverage, dragged down by the leaky columns that merely re-encode the outcome."
}

